insert into public.flashcards (id, cert, deck, domain, objective, front, back) values
('sc-f-054','awsscs','core',1,'1.1',$$What is GuardDuty Malware Protection?$$,$$Automatically scans EBS volumes attached to EC2/container workloads flagged by GuardDuty findings for malware, without requiring an agent on the instance.$$),
('sc-f-055','awsscs','core',1,'1.2',$$What is AWS Systems Manager Incident Manager?$$,$$Automates incident response: triggers runbooks, pages on-call responders, and tracks a structured timeline when a CloudWatch alarm or manual trigger fires.$$),
('sc-f-056','awsscs','core',1,'1.1',$$What is a Security Hub custom insight?$$,$$A saved, reusable query grouping findings by any attribute (e.g., all high-severity EC2 findings) for quick repeated triage views.$$),
('sc-f-057','awsscs','core',2,'2.1',$$What is CloudTrail Insights?$$,$$Automatically detects unusual API call volume or error rate patterns in CloudTrail data, surfacing anomalies without manually defining every rule.$$),
('sc-f-058','awsscs','core',2,'2.2',$$What is Amazon CloudWatch Logs Insights?$$,$$A query language/console for interactively searching and analyzing log data already stored in CloudWatch Logs, without needing an external SIEM.$$),
('sc-f-059','awsscs','core',2,'2.1',$$What is a CloudTrail data event vs a management event?$$,$$Management events record control-plane actions (creating a bucket); data events record data-plane actions (an object being read from that bucket) - data events cost extra and are opt-in due to volume.$$),
('sc-f-060','awsscs','core',2,'2.2',$$What is Amazon Macie's role in logging/monitoring?$$,$$Continuously scans S3 for sensitive data and alerts on exposure or unusual access, functioning as a data-focused monitoring layer alongside infrastructure logs.$$),
('sc-f-061','awsscs','core',2,'2.1',$$What is VPC Traffic Mirroring used for?$$,$$Copies live network traffic from an ENI to a security/monitoring appliance for deep packet inspection, without disrupting the original traffic flow.$$),
('sc-f-062','awsscs','core',3,'3.1',$$What is AWS PrivateLink?$$,$$Provides private connectivity between VPCs and supported AWS/partner/customer services via interface endpoints, without traversing the public internet or requiring VPC peering.$$),
('sc-f-063','awsscs','core',3,'3.1',$$What is a security group referencing another security group?$$,$$Instead of hardcoding IP ranges, a rule allows traffic FROM instances that belong to a specified security group - stays correct automatically as instances scale in/out.$$),
('sc-f-064','awsscs','core',3,'3.2',$$What is AWS Shield Advanced's cost protection?$$,$$Credits back the costs of scaling (e.g., extra CloudFront/ELB usage) incurred specifically due to a DDoS attack, protecting the customer from a bill spike caused by the attack itself.$$),
('sc-f-065','awsscs','core',3,'3.1',$$What does a bastion-free architecture using SSM Session Manager eliminate?$$,$$No inbound SSH/RDP ports at all - instances only need outbound HTTPS to the Systems Manager endpoint, drastically shrinking the network attack surface.$$),
('sc-f-066','awsscs','core',3,'3.2',$$What is geographic/geo-match blocking in AWS WAF?$$,$$A rule blocking or allowing requests based on the country the request originates from, useful for restricting access to expected markets.$$),
('sc-f-067','awsscs','core',4,'4.1',$$What is an IAM Access Analyzer archive rule?$$,$$Automatically archives (marks as expected, not alerting) findings that match a known, intentional pattern of external access, reducing noise from legitimate shared resources.$$),
('sc-f-068','awsscs','core',4,'4.2',$$What is AWS IAM Identity Center attribute-based access control (ABAC)?$$,$$Assigns permissions based on user attributes (department, cost center) synced from the identity source, rather than maintaining a role per department manually.$$),
('sc-f-069','awsscs','core',4,'4.1',$$How does a permissions boundary enable safe self-service IAM role creation?$$,$$It lets you delegate "create your own IAM roles" to developers, because the boundary caps whatever permissions they might grant themselves or others, regardless of what they attempt.$$),
('sc-f-070','awsscs','core',4,'4.1',$$What is the difference between an IAM policy's NotAction and Action elements?$$,$$Action explicitly lists what's allowed/denied; NotAction is a shorthand for "everything except these" - useful for broad deny statements naming a small exception list.$$),
('sc-f-071','awsscs','core',5,'5.1',$$What is a KMS grant's constraint capability?$$,$$Grants can restrict delegated key operations to specific encryption contexts, further limiting what the delegated principal can actually do with the temporary permission.$$),
('sc-f-072','awsscs','core',5,'5.2',$$What is S3 Object Lock?$$,$$WORM (write-once-read-many) protection at the object level - prevents deletion or overwrite for a retention period or indefinitely (legal hold), even by the account root user in compliance mode.$$),
('sc-f-073','awsscs','core',5,'5.1',$$What is the difference between KMS symmetric and asymmetric keys?$$,$$Symmetric: same key encrypts and decrypts, used for most AWS service integrations. Asymmetric: public/private key pair, used for scenarios needing to share the public key externally (signing, offline encryption).$$),
('sc-f-074','awsscs','core',5,'5.2',$$What is Macie's sensitive data discovery job scope?$$,$$Configurable to scan all buckets, specific buckets, or sample a percentage of objects - balancing thoroughness against scanning cost for very large data lakes.$$),
('sc-f-075','awsscs','core',5,'5.1',$$What is a KMS custom key store?$$,$$Backs a KMS key with your own CloudHSM cluster instead of AWS's default key store, giving you direct control over the underlying HSM while keeping the KMS API interface.$$),
('sc-f-076','awsscs','core',6,'6.1',$$What is AWS Organizations tag policies?$$,$$Enforce consistent tagging rules (required keys, allowed values) across accounts in an Organization, supporting cost allocation and governance automation.$$),
('sc-f-077','awsscs','core',6,'6.2',$$What is AWS Audit Manager?$$,$$Continuously collects evidence mapped to a chosen compliance framework, reducing the manual effort of preparing for audits by automating evidence gathering.$$),
('sc-f-078','awsscs','core',6,'6.1',$$What is a typical landing zone account structure?$$,$$Separate accounts for management/root, log archive, security/audit tooling, and workload environments (dev/test/prod) - isolating blast radius and responsibilities.$$);
insert into public.questions (id, cert, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
('sc-q-051','awsscs',1,'1.1','mcq',2,$q$A GuardDuty finding flags an EC2 instance as potentially compromised. Which AWS capability can automatically scan the instance's attached EBS volumes for malware without installing an agent?$q$,$q$["GuardDuty Malware Protection","Amazon Inspector","AWS Config","CloudTrail"]$q$::jsonb,'0'::jsonb,$q$GuardDuty Malware Protection triggers agentless EBS volume scanning in response to relevant findings, without requiring software on the instance itself.$q$),
('sc-q-052','awsscs',1,'1.2','mcq',2,$q$A security team wants CloudWatch alarms to automatically page an on-call responder, launch a documented runbook, and track a timeline of response actions. Which service fits?$q$,$q$["AWS Systems Manager Incident Manager","Amazon S3","AWS Direct Connect","Amazon Route 53"]$q$::jsonb,'0'::jsonb,$q$Incident Manager automates the operational side of incident response: paging, runbook execution, and timeline tracking triggered by alarms or manual activation.$q$),
('sc-q-053','awsscs',1,'1.1','mcq',2,$q$An analyst wants a saved, reusable view showing only high-severity Security Hub findings on EC2 instances, without rebuilding the filter every time. What should they create?$q$,$q$["A custom insight","A new AWS account","A CloudFront distribution","A Route 53 record"]$q$::jsonb,'0'::jsonb,$q$Custom insights save a reusable filtered view of findings, letting analysts return to the same triage query repeatedly without reconstructing it.$q$),
('sc-q-054','awsscs',1,'1.1','mcq',3,$q$Which service builds a visual, linked graph of entities (IPs, users, resources) involved in a GuardDuty finding to help scope an investigation?$q$,$q$["Amazon Detective","AWS Config","Amazon S3","AWS Direct Connect"]$q$::jsonb,'0'::jsonb,$q$Detective builds behavior graphs linking related entities and events from GuardDuty/CloudTrail/VPC Flow Logs, purpose-built for investigation and scoping.$q$),
('sc-q-055','awsscs',1,'1.2','mcq',2,$q$An EventBridge rule matches a specific GuardDuty finding type and invokes a Lambda function that automatically revokes the affected IAM user's active sessions. What pattern is this?$q$,$q$["Automated remediation via event-driven response","Manual ticketing only","A one-time script with no automation","A CloudFormation template"]$q$::jsonb,'0'::jsonb,$q$Chaining a finding to an EventBridge rule and Lambda function creates automated, immediate remediation without waiting on manual analyst action.$q$),
('sc-q-056','awsscs',1,'1.1','mcq',2,$q$Why does GuardDuty Malware Protection scan EBS volumes rather than requiring an agent inside the EC2 instance?$q$,$q$["It cannot detect malware at all","Agentless scanning avoids deploying and maintaining software on every instance while still inspecting the volume's contents","Agents are required and this scenario is impossible","EBS volumes cannot be scanned"]$q$::jsonb,'1'::jsonb,$q$The agentless design inspects volume snapshots directly, avoiding the operational burden of deploying and maintaining scanning agents fleet-wide.$q$),
('sc-q-057','awsscs',2,'2.1','mcq',2,$q$A security team wants to know if API call volume on a critical account suddenly spikes without manually writing a threshold rule for every API. What CloudTrail feature detects this automatically?$q$,$q$["CloudTrail Insights","CloudTrail data events only","VPC Flow Logs","AWS Config"]$q$::jsonb,'0'::jsonb,$q$CloudTrail Insights automatically baselines normal API activity and flags statistically unusual volume or error-rate deviations without manual rule authoring.$q$),
('sc-q-058','awsscs',2,'2.2','mcq',2,$q$An analyst needs to interactively query CloudWatch Logs data using a purpose-built query syntax, without exporting to an external tool. What should they use?$q$,$q$["CloudWatch Logs Insights","AWS Budgets","Amazon Route 53","AWS Direct Connect"]$q$::jsonb,'0'::jsonb,$q$Logs Insights provides a native query language for ad hoc, interactive analysis directly against stored CloudWatch Logs data.$q$),
('sc-q-059','awsscs',2,'2.1','mcq',3,$q$A company wants to log every S3 GetObject call for a specific bucket, not just bucket-level management actions like CreateBucket. What must they enable?$q$,$q$["CloudTrail data events for that bucket","Management events only (the default)","VPC Flow Logs","Nothing extra is needed"]$q$::jsonb,'0'::jsonb,$q$Object-level access is a data-plane action, only captured by data events - management events (the default) only cover control-plane actions like bucket creation.$q$),
('sc-q-060','awsscs',2,'2.2','mcq',2,$q$A company wants continuous automated scanning of its S3 buckets for exposed PII, with alerts on unusual access patterns. Which service fits?$q$,$q$["Amazon Macie","AWS Direct Connect","Amazon Route 53","AWS Budgets"]$q$::jsonb,'0'::jsonb,$q$Macie uses ML to discover and classify sensitive data in S3 and alerts on exposure or anomalous access - purpose-built for this scenario.$q$),
('sc-q-061','awsscs',2,'2.1','mcq',3,$q$A security team needs to perform deep packet inspection on live traffic from a specific EC2 instance without disrupting its normal network flow. What should they configure?$q$,$q$["VPC Traffic Mirroring to a monitoring appliance","Deleting the instance","VPC Flow Logs only","CloudTrail"]$q$::jsonb,'0'::jsonb,$q$Traffic Mirroring copies live traffic to an inspection target without interrupting or altering the original flow, enabling deep packet inspection.$q$),
('sc-q-062','awsscs',2,'2.1','mcq',2,$q$Why might an organization enable CloudTrail data events for S3 despite the added cost and volume?$q$,$q$["Data events are free","Object-level access (reads/writes) is invisible in management events alone, and may be required for forensic reconstruction of a data breach","Data events replace the need for management events","Data events are mandatory for all accounts"]$q$::jsonb,'1'::jsonb,$q$Investigating a suspected data breach often requires knowing exactly which objects were read or written - visibility only data events provide.$q$),
('sc-q-063','awsscs',2,'2.2','mcq',2,$q$Which combination gives the most complete picture of a potential data exfiltration event: which S3 objects were accessed, who accessed them, and if the data was sensitive?$q$,$q$["CloudTrail data events plus Amazon Macie classification","VPC Flow Logs alone","Route 53 query logs alone","AWS Budgets alone"]$q$::jsonb,'0'::jsonb,$q$Data events show WHO accessed WHICH objects; Macie classification tells you whether that data was sensitive - together they answer the full exfiltration question.$q$),
('sc-q-064','awsscs',2,'2.1','mcq',2,$q$A compliance requirement mandates that all CloudTrail logs across 30 accounts be centrally aggregated and tamper-evident. Which combination satisfies this?$q$,$q$["An organization trail delivering to a locked-down logging account bucket with log file validation enabled","Per-account trails each admin manages independently","Disabling CloudTrail to reduce cost","VPC Flow Logs instead of CloudTrail"]$q$::jsonb,'0'::jsonb,$q$An organization trail centralizes logging beyond any single account's control, and log file validation provides cryptographic tamper-evidence.$q$),
('sc-q-065','awsscs',3,'3.1','mcq',2,$q$A company wants private connectivity from its VPC to a SaaS partner's service hosted in another AWS account, without VPC peering or exposing traffic to the internet. What should they use?$q$,$q$["AWS PrivateLink","A public NAT Gateway","An Internet Gateway","VPC peering across accounts"]$q$::jsonb,'0'::jsonb,$q$PrivateLink creates an interface endpoint for private, cross-account service access without peering or internet exposure - purpose-built for this SaaS connectivity pattern.$q$),
('sc-q-066','awsscs',3,'3.1','mcq',2,$q$An Auto Scaling group's instances need to accept traffic only from the load balancer's instances, whose IPs change as it scales. What security group configuration avoids hardcoding IPs?$q$,$q$["Referencing the load balancer's security group as the source in the inbound rule","Allowing 0.0.0.0/0","Manually updating IP ranges daily","Disabling the security group"]$q$::jsonb,'0'::jsonb,$q$Security-group-referencing rules stay correct automatically as instances scale, since the rule targets group membership rather than specific, changing IP addresses.$q$),
('sc-q-067','awsscs',3,'3.2','mcq',3,$q$During a large DDoS attack, a company's CloudFront and ELB usage spikes dramatically, driving up their bill. Which Shield Advanced feature protects them from this specific cost spike?$q$,$q$["Shield Advanced cost protection, crediting scaling costs incurred due to the attack","Shield Standard only","There is no such protection","AWS Budgets prevents the attack"]$q$::jsonb,'0'::jsonb,$q$Shield Advanced specifically credits back scaling costs directly attributable to a DDoS attack, protecting customers from an attack-driven bill spike.$q$),
('sc-q-068','awsscs',3,'3.1','mcq',2,$q$A company wants zero inbound management ports open on any EC2 instance while still allowing administrators to get a shell. What architecture achieves this?$q$,$q$["SSM Session Manager, requiring only outbound HTTPS from the instance","An SSH bastion with port 22 open","RDP directly to each instance","A VPN with inbound port 3389"]$q$::jsonb,'0'::jsonb,$q$Session Manager needs only an outbound connection to the Systems Manager endpoint - no inbound SSH/RDP ports at all, eliminating that entire attack surface.$q$),
('sc-q-069','awsscs',3,'3.2','mcq',2,$q$A company must block web traffic from countries where they do not operate, for compliance and abuse-reduction reasons. Which WAF capability fits?$q$,$q$["Geographic (geo-match) blocking rules","Rate-based rules only","IP set matching only","SQL injection rules only"]$q$::jsonb,'0'::jsonb,$q$Geo-match rules filter by request origin country directly - the purpose-built WAF feature for this exact restriction.$q$),
('sc-q-070','awsscs',3,'3.1','mcq',2,$q$Which statement about AWS PrivateLink is correct?$q$,$q$["It requires VPC peering to function","It creates an ENI-based interface endpoint in the consumer's VPC, keeping traffic on the AWS network without peering or internet exposure","It only works for S3 and DynamoDB","It is identical to a NAT Gateway"]$q$::jsonb,'1'::jsonb,$q$PrivateLink's interface endpoints live directly in the consumer's VPC as ENIs, requiring no peering and keeping all traffic on AWS's private network.$q$),
('sc-q-071','awsscs',3,'3.1','mcq',3,$q$A company runs workloads across ten VPCs and wants a single, centrally managed WAF/Shield Advanced/security group policy applied consistently across all of them. Which service enables this?$q$,$q$["AWS Firewall Manager","A per-VPC manual configuration","AWS Budgets","Amazon Route 53"]$q$::jsonb,'0'::jsonb,$q$Firewall Manager centrally configures and enforces WAF, Shield Advanced, and security group policies consistently across many accounts/VPCs in an Organization.$q$),
('sc-q-072','awsscs',3,'3.2','mcq',2,$q$Which combination of controls provides layered defense against a Layer 7 HTTP flood targeting a public web application?$q$,$q$["WAF rate-based rules plus Shield Advanced plus CloudFront caching","A security group alone","Disabling the web server during business hours","Removing DNS records permanently"]$q$::jsonb,'0'::jsonb,$q$Layered application-layer DDoS defense combines rate limiting (WAF), managed mitigation (Shield Advanced), and absorbing legitimate load via caching (CloudFront).$q$),
('sc-q-073','awsscs',3,'3.1','mcq',2,$q$Why is security-group-referencing (pointing to another security group as the source) preferred over hardcoded IP ranges in a dynamic Auto Scaling environment?$q$,$q$["It automatically stays correct as instances scale in and out, unlike static IP lists that go stale","It has no real advantage","Hardcoded IPs are always more secure","Security groups cannot reference other security groups"]$q$::jsonb,'0'::jsonb,$q$Referencing group membership rather than specific IPs means the rule remains accurate without manual updates as the fleet scales dynamically.$q$),
('sc-q-074','awsscs',4,'4.1','mcq',2,$q$IAM Access Analyzer repeatedly flags the same intentional cross-account access pattern used for a legitimate shared analytics bucket. How can the team reduce this recurring noise?$q$,$q$["An archive rule matching that known pattern","Deleting the analytics bucket","Disabling Access Analyzer entirely","Ignoring all future findings"]$q$::jsonb,'0'::jsonb,$q$Archive rules automatically suppress alerts for known, intentional access patterns while leaving Access Analyzer active for genuinely unexpected findings.$q$),
('sc-q-075','awsscs',4,'4.2','mcq',3,$q$A company wants new employees to automatically receive correct permissions based on their department attribute synced from the HR system, without manually assigning a role per hire. What IAM Identity Center approach fits?$q$,$q$["Attribute-based access control (ABAC)","Creating a unique IAM user per employee with hardcoded permissions","Sharing one admin account","Disabling permission sets"]$q$::jsonb,'0'::jsonb,$q$ABAC ties permissions to synced attributes (like department), so access updates automatically as attributes change, without manual per-user role assignment.$q$),
('sc-q-076','awsscs',4,'4.1','mcq',2,$q$A company wants to let developers create their own IAM roles for their projects, but ensure none of those self-created roles can ever exceed a defined maximum permission set. What should be applied to the developers' own IAM identities?$q$,$q$["A permissions boundary","A resource-based policy only","No control - developers should have full freedom","A NAT Gateway"]$q$::jsonb,'0'::jsonb,$q$A permissions boundary caps what a developer (and anything they create) can be granted, making self-service role creation safe to delegate.$q$),
('sc-q-077','awsscs',4,'4.1','mcq',2,$q$Which IAM policy element expresses "deny everything except these two specific actions" most concisely?$q$,$q$["NotAction combined with Deny","Action listing every single AWS action individually","A resource-based policy only","There is no way to express this"]$q$::jsonb,'0'::jsonb,$q$NotAction paired with Deny inverts the action list, denying everything NOT named - far more concise than enumerating every possible action to exclude.$q$),
('sc-q-078','awsscs',4,'4.2','mcq',2,$q$Why is ABAC often preferred over RBAC at large organizational scale for IAM Identity Center deployments?$q$,$q$["ABAC requires creating a role for every possible attribute combination","ABAC scales without needing a new role definition for every new department/attribute combination, reducing role sprawl","RBAC always scales better","ABAC cannot be used with IAM Identity Center"]$q$::jsonb,'1'::jsonb,$q$ABAC evaluates attributes dynamically rather than requiring a discrete role per combination, avoiding the role sprawl RBAC accumulates at scale.$q$),
('sc-q-079','awsscs',4,'4.1','mcq',3,$q$A security review finds hundreds of unused IAM roles created over several years with no clear ownership. Which combination of tools helps identify and safely clean these up?$q$,$q$["IAM Access Analyzer unused access findings plus CloudTrail last-accessed data","Deleting all roles immediately without review","Ignoring the finding since roles don't expire","Recreating the roles"]$q$::jsonb,'0'::jsonb,$q$Access Analyzer's unused access findings combined with last-accessed data give evidence-based confidence about which roles are genuinely safe to remove.$q$),
('sc-q-080','awsscs',4,'4.2','mcq',2,$q$Which is the correct capability of IAM Access Analyzer beyond identifying external access?$q$,$q$["It can also generate least-privilege policies based on actual CloudTrail activity","It can only detect external access, nothing else","It automatically deletes flagged resources","It replaces the need for IAM entirely"]$q$::jsonb,'0'::jsonb,$q$Access Analyzer also has a policy generation feature that proposes least-privilege policies derived from observed CloudTrail activity.$q$),
('sc-q-081','awsscs',5,'5.1','mcq',3,$q$A company wants to delegate a Lambda function the ability to use a KMS key ONLY when a specific encryption context matches an expected value, not for any other operation. What KMS feature enables this constraint?$q$,$q$["A grant with an encryption context constraint","A fully open key policy","Disabling the key","A public S3 bucket"]$q$::jsonb,'0'::jsonb,$q$KMS grants support encryption context constraints, scoping the delegated permission tightly to the intended use case rather than any use of the key.$q$),
('sc-q-082','awsscs',5,'5.2','mcq',2,$q$A financial company must ensure certain records cannot be deleted or modified by ANYONE, including the account root user, for a legally mandated retention period. Which S3 feature enforces this?$q$,$q$["S3 Object Lock in compliance mode","S3 Versioning alone","A bucket policy alone","IAM permissions alone"]$q$::jsonb,'0'::jsonb,$q$Object Lock in compliance mode cannot be overridden or shortened by any principal, including root - the strongest available WORM enforcement.$q$),
('sc-q-083','awsscs',5,'5.1','mcq',2,$q$An application needs to share a public key externally so partners can verify signatures, while keeping the private key secured within AWS. Which KMS key type fits?$q$,$q$["An asymmetric KMS key pair","A symmetric KMS key","No KMS key is needed","A Secrets Manager secret"]$q$::jsonb,'0'::jsonb,$q$Asymmetric KMS keys allow exporting/sharing the public key for external signature verification while the private key never leaves KMS.$q$),
('sc-q-084','awsscs',5,'5.2','mcq',2,$q$A company has a massive data lake and wants to control Macie's scanning cost by sampling 10% of objects rather than scanning every object in every job run. What should they configure?$q$,$q$["A Macie sensitive data discovery job with a defined sampling percentage","Full scanning of every object regardless of cost","Disabling Macie","Manual review of every file"]$q$::jsonb,'0'::jsonb,$q$Macie discovery jobs support configurable sampling percentages, balancing scanning cost against coverage for very large datasets.$q$),
('sc-q-085','awsscs',5,'5.1','mcq',3,$q$A regulated company requires that its KMS keys be backed by dedicated hardware it directly controls, rather than AWS's shared default key store, while still using the standard KMS API. What should they configure?$q$,$q$["A KMS custom key store backed by CloudHSM","A standard AWS-managed KMS key","Disabling KMS and using local encryption only","S3 default encryption alone"]$q$::jsonb,'0'::jsonb,$q$A custom key store lets a dedicated CloudHSM cluster back KMS keys, satisfying dedicated-hardware requirements while preserving the familiar KMS API.$q$),
('sc-q-086','awsscs',5,'5.2','mcq',2,$q$Which data protection combination BEST defends against accidental permanent deletion of critical compliance records in S3?$q$,$q$["Versioning plus Object Lock in compliance mode","No protection needed","Deleting old versions immediately","A public bucket policy"]$q$::jsonb,'0'::jsonb,$q$Versioning preserves prior states and Object Lock prevents deletion/overwrite entirely for the retention period - together they defend against both accidental and malicious loss.$q$),
('sc-q-087','awsscs',5,'5.1','mcq',2,$q$Why would an application choose a KMS symmetric key over an asymmetric key pair for encrypting data that only the same application will ever decrypt?$q$,$q$["Symmetric keys are the standard, simpler choice for this same-party encrypt/decrypt pattern and integrate natively with most AWS services","Asymmetric keys are always required","Symmetric keys cannot be used with AWS services","There is no difference between the two"]$q$::jsonb,'0'::jsonb,$q$When the same party encrypts and decrypts, symmetric keys are simpler and integrate directly with most AWS service encryption features - asymmetric keys solve a different problem (sharing the public half).$q$),
('sc-q-088','awsscs',5,'5.2','mcq',3,$q$A company sets S3 Object Lock retention to 7 years in GOVERNANCE mode rather than COMPLIANCE mode. What is the practical difference?$q$,$q$["Governance mode allows users with special permissions to override the lock; compliance mode cannot be overridden by anyone, including the root user","They are functionally identical","Governance mode is stricter than compliance mode","Object Lock modes only affect versioning, not deletion"]$q$::jsonb,'0'::jsonb,$q$Governance mode permits specially-permissioned users to bypass the lock when genuinely needed; compliance mode is absolute and cannot be overridden by anyone.$q$),
('sc-q-089','awsscs',6,'6.1','mcq',2,$q$A company wants every resource across its Organization to carry a required "CostCenter" tag with only approved values, enforced automatically. What should they configure?$q$,$q$["An AWS Organizations tag policy","A manual spreadsheet review","An SCP with no tag logic","Deleting untagged resources with no warning"]$q$::jsonb,'0'::jsonb,$q$Tag policies enforce consistent required keys and allowed values across accounts, automating what would otherwise be manual tagging governance.$q$),
('sc-q-090','awsscs',6,'6.2','mcq',2,$q$An organization spends weeks manually gathering evidence for each compliance audit. Which service continuously collects evidence mapped to a chosen framework to reduce this effort?$q$,$q$["AWS Audit Manager","AWS Budgets","Amazon Route 53","AWS Direct Connect"]$q$::jsonb,'0'::jsonb,$q$Audit Manager continuously gathers evidence aligned to a selected framework, dramatically reducing the manual audit-preparation burden.$q$),
('sc-q-091','awsscs',6,'6.1','mcq',2,$q$In a typical AWS landing zone, why are logging and security/audit tooling placed in SEPARATE accounts from workload accounts?$q$,$q$["To isolate blast radius - a compromised workload account cannot tamper with centralized logs or audit tooling in a separate, locked-down account","Separate accounts are required by AWS for all workloads","It has no security benefit, only organizational tidiness","Logs cannot be stored in the same account as workloads under any circumstances"]$q$::jsonb,'0'::jsonb,$q$Separating log/audit accounts means a workload compromise can't reach or tamper with the evidence needed to investigate that very compromise.$q$),
('sc-q-092','awsscs',6,'6.1','mcq',3,$q$Which governance mechanism would prevent an account administrator from ever disabling GuardDuty in their own account, even with full IAM admin rights?$q$,$q$["An SCP explicitly denying guardduty:DisassociateFromMasterAccount and similar disable actions, applied at the OU level","An IAM policy in that same account","A CloudWatch alarm alone","Nothing can prevent this"]$q$::jsonb,'0'::jsonb,$q$Only an SCP applied above the account (at the OU or org level) can override even a full-admin account holder, since SCPs are evaluated regardless of local IAM permissions.$q$),
('sc-q-093','awsscs',6,'6.2','mcq',2,$q$Which AWS service specifically evaluates an account against best-practice checks across cost, security, performance, and fault tolerance, distinct from continuous compliance-framework evidence collection?$q$,$q$["AWS Trusted Advisor","AWS Audit Manager","Amazon GuardDuty","AWS Config"]$q$::jsonb,'0'::jsonb,$q$Trusted Advisor checks broad best-practice categories directly; Audit Manager instead maps evidence to a specific external compliance framework - different purposes.$q$),
('sc-q-094','awsscs',6,'6.1','mcq',2,$q$A landing zone separates the management/root account from all workload accounts. What is the PRIMARY security reason for this?$q$,$q$["The root/management account has organization-wide power (billing, SCPs, member account management) that should never be mixed with day-to-day workload risk","It reduces AWS billing","It is only for cosmetic organization","Root accounts cannot host any resources"]$q$::jsonb,'0'::jsonb,$q$The management account's organization-wide control plane power makes it far too sensitive to also run everyday workloads that carry ordinary operational risk.$q$),
('sc-q-095','awsscs',6,'6.2','mcq',2,$q$Which combination gives both continuous best-practice checking AND structured compliance-framework evidence collection for an upcoming audit?$q$,$q$["AWS Trusted Advisor plus AWS Audit Manager","Neither is necessary","A single spreadsheet","Manual screenshots only"]$q$::jsonb,'0'::jsonb,$q$Trusted Advisor's ongoing best-practice checks and Audit Manager's framework-mapped evidence collection together cover both continuous posture and audit-readiness needs.$q$);
